function ON_ITELINES_MTRL() {
var supplier = PURDOC.TRDR;
var vmtrl = ITELINES.MTRL;
ITELINES.PRICE = ITELINES.MTRL_ITEM_PRICEW01;
var SQLhistoryS1 =
"IF EXISTS (SELECT TOP 1 1 FROM MTRTRN XX WHERE XX.MTRL = '" + vmtrl + "' AND XX.TRDR = '" + supplier + "' AND XX.SOSOURCE = 1251) " +
"SELECT TOP 1 XX.DISCPRC AS DISC FROM MTRTRN XX WHERE XX.MTRL = '" + vmtrl + "' AND XX.TRDR = '" + supplier + "' AND XX.SOSOURCE = 1251 AND XX.SERIES <> 2066 ORDER BY XX.TRNDATE DESC ELSE SELECT -1 AS DISC";
var dssS1 = X.GETSQLDATASET(SQLhistoryS1, null);
var vdiscS1 = dssS1.DISC;
ITELINES.V6 = S1P.Round(vdiscS1,2);
if (ITELINES.V6 > 0) ITELINES.DISC1PRC = ITELINES.V6;
X.WARNING('ΠΡΟΣΟΧΗ!');
}

