function Findocs() {
var qFindoc = X.GETSQLDATASET("SELECT FINDOC FROM FINDOC WHERE FISCPRD = 2025 AND PERIOD = 1 AND SOSOURCE = 1351 AND SERIES != 790 AND FPRMS = 7090 AND COMPANY = 1004 ORDER BY FINDOC",null);
while (!qFindoc.EOF) {
var curFindoc = qFindoc.FINDOC;
var myObj = X.CREATEOBJ('SALDOC');
myObj.DBLocate(curFindoc);
myObj.Edit;
myObj.DBPost;
qFindoc.Next;
}
X.WARNING("DONE");
}

